-- Diagrams to look at: the ones the editor is tested with. The editor has no
-- data of its own, so these are what it shows at first. Optional, and for a
-- database that is still empty apart from the legal entity types: it counts on
-- the sample funds getting the ids 1 to 24.
--
--   Sample fund structure LE 24        24 funds,   26 relationships
--   30 generated funds LE 30           30 funds,   44 relationships
--   100 generated funds LE 100        100 funds,  149 relationships
--   200 generated funds LE 200        200 funds,  299 relationships
--   500 generated funds LE 500        500 funds,  749 relationships
--   1000 generated funds LE 1000     1000 funds, 1499 relationships
--   2000 generated funds LE 2000     2000 funds, 2999 relationships
--   Empty diagram LE 0                  0 funds,    0 relationships
--
-- "LE" in a name is the number of legal entities (funds) of the diagram. It is
-- written without a colon, because a name is letters, digits and spaces only.
--
-- Every diagram has funds of its own: 3854 legal entities in all. The sample
-- has its funds where the editor's layout places them; the generated diagrams
-- have no positions, so the editor arranges each when it is opened. The sample
-- funds also get four user-defined fields with a few values.
--
-- This file is generated from the data of the editor's tests (src/testing/datasets.ts);
-- it is not meant to be edited by hand.
begin;
  -- The funds and their relationships as the editor numbers them, per diagram:
  -- "key" is the number of a fund within its diagram.
  create temp table seed_fund (
    ord     integer generated always as identity primary key,
    diagram text not null,
    key     integer not null,
    name    text not null,
    type    text not null,
    x       double precision,
    y       double precision,
    comment text not null,
    id      bigint
  ) on commit drop;
  create temp table seed_stake (
    ord       integer generated always as identity primary key,
    diagram   text not null,
    from_key  integer not null,
    to_key    integer not null,
    kind      text not null,
    ownership numeric(5, 2)
  ) on commit drop;

  insert into seed_fund (diagram, key, name, type, x, y, comment) values
