    ('2000 generated funds LE 2000',174,312,'relation',26.55),
    ('2000 generated funds LE 2000',26,495,'relation',28.09),
    ('2000 generated funds LE 2000',24,1121,'relation',null),
    ('2000 generated funds LE 2000',99,1661,'relation',null),
    ('2000 generated funds LE 2000',125,1029,'relation',null),
    ('2000 generated funds LE 2000',255,331,'relation',20.1),
    ('2000 generated funds LE 2000',589,1100,'relation',36.18);

  -- Every fund becomes a legal entity. The ids are handed out one by one, in the
  -- order of the rows above, so that the sample funds are the first.
  do $$
  declare
    fund record;
  begin
    for fund in select ord from seed_fund order by ord loop
      update seed_fund
      set id = nextval(pg_get_serial_sequence('legal_entity', 'id'))
      where ord = fund.ord;
    end loop;
  end $$;
  insert into legal_entity (id, name, legal_entity_type_id)
    overriding system value
    select f.id, f.name, t.id
    from seed_fund f
    join legal_entity_type t on t.name = f.type
    order by f.ord;

  insert into relationship (from_legal_entity_id, to_legal_entity_id, kind, ownership_percent)
    select f.id, t.id, s.kind, s.ownership
    from seed_stake s
    join seed_fund f on f.diagram = s.diagram and f.key = s.from_key
    join seed_fund t on t.diagram = s.diagram and t.key = s.to_key
    order by s.ord;

  -- The diagrams, the sample first. In the list of diagrams the one
  -- changed last comes first, so the sample is the newest.
  insert into diagram (name, description, created_at, updated_at) values
    ('Sample fund structure LE 24', '24 funds and 26 relationships', now() - interval '24 days', now() - interval '0 hours'),
    ('30 generated funds LE 30', '30 funds and 44 relationships', now() - interval '21 days', now() - interval '5 hours'),
    ('100 generated funds LE 100', '100 funds and 149 relationships', now() - interval '18 days', now() - interval '10 hours'),
    ('200 generated funds LE 200', '200 funds and 299 relationships', now() - interval '15 days', now() - interval '15 hours'),
    ('500 generated funds LE 500', '500 funds and 749 relationships', now() - interval '12 days', now() - interval '20 hours'),
    ('1000 generated funds LE 1000', '1000 funds and 1499 relationships', now() - interval '9 days', now() - interval '25 hours'),
    ('2000 generated funds LE 2000', '2000 funds and 2999 relationships', now() - interval '6 days', now() - interval '30 hours'),
    ('Empty diagram LE 0', 'A diagram without funds', now() - interval '3 days', now() - interval '35 hours');

  -- Colour and shape are left to their defaults: light gray rectangles.
  insert into diagram_node (diagram_id, legal_entity_id, x, y, comment)
    select d.id, f.id, f.x, f.y, f.comment
    from seed_fund f
    join diagram d on d.name = f.diagram;

  -- Four fields that users might define, one of each type.
  insert into user_defined_field (name, data_type, is_optional) values
    ('Jurisdiction', 'text', false),
    ('Inception date', 'date', true),
    ('Assets under management in EUR m', 'number', true),
    ('Regulated', 'boolean', true);

  -- Some funds have some of them; most funds have none.
  insert into legal_entity_field_value (legal_entity_id, user_defined_field_id, value_text)
    select e.id, f.id, v.value
    from (values ('Meridian Global FoF', 'Luxembourg'), ('Meridian PE Feeder', 'Ireland'),
                 ('Buyout Fund IV', 'Luxembourg'), ('Growth Fund II', 'Cayman Islands')) v(entity, value)
    join seed_fund s on s.name = v.entity and s.diagram like 'Sample fund structure%'
    join legal_entity e on e.id = s.id
    join user_defined_field f on f.name = 'Jurisdiction';
  insert into legal_entity_field_value (legal_entity_id, user_defined_field_id, value_date)
    select e.id, f.id, v.value::date
    from (values ('Meridian Global FoF', '2014-03-01'), ('Buyout Fund IV', '2019-09-15')) v(entity, value)
    join seed_fund s on s.name = v.entity and s.diagram like 'Sample fund structure%'
    join legal_entity e on e.id = s.id
    join user_defined_field f on f.name = 'Inception date';
  insert into legal_entity_field_value (legal_entity_id, user_defined_field_id, value_number)
    select e.id, f.id, v.value
    from (values ('Meridian Global FoF', 1850.5), ('Buyout Fund IV', 420)) v(entity, value)
    join seed_fund s on s.name = v.entity and s.diagram like 'Sample fund structure%'
    join legal_entity e on e.id = s.id
    join user_defined_field f on f.name = 'Assets under management in EUR m';
  insert into legal_entity_field_value (legal_entity_id, user_defined_field_id, value_boolean)
    select e.id, f.id, true
    from seed_fund e, user_defined_field f
    where e.name = 'Meridian Global FoF' and e.diagram like 'Sample fund structure%'
      and f.name = 'Regulated';
  -- A fund that has a field without a value for it yet: allowed, because the field is optional.
  insert into legal_entity_field_value (legal_entity_id, user_defined_field_id)
    select e.id, f.id
    from seed_fund e, user_defined_field f
    where e.name = 'Growth Fund II' and e.diagram like 'Sample fund structure%'
      and f.name = 'Inception date';
commit;
